package br.com.lealinfo.vidraceiro;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.media.ExifInterface;import android.net.Uri;import android.provider.MediaStore;import android.text.*;import android.view.*;import android.widget.*;import androidx.core.content.FileProvider;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 private final ArrayList<Row> rows=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private LinearLayout root,measureBox;private AutoCompleteTextView type;private EditText title,model,config;private ImageView photo,result;private TextView status;private Button create,send;private String id,simulation="";private int revision=0;private boolean restoring=false,busy=false;private File dir;
 private static final String[] TYPES={"Janela","Porta","Box de banheiro","Espelho","Vidro fixo","Divisória","Fechamento","Guarda-corpo","Esquadria"};
 private int px(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});
  id=getPreferences(0).getString("current",UUID.randomUUID().toString());setDir();ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(px(20),px(16),px(20),px(30));root.setBackgroundColor(Color.rgb(8,18,36));scroll.addView(root);setContentView(scroll);
  label("LEAL INFO • VIDRACEIRO",24);label("Foto + medidas reais + serviço → simulação",15);button("CONEXÃO DO SERVIÇO / PDV",this::connection);
  title=edit("Nome do projeto",false);type=new AutoCompleteTextView(this);style(type);type.setHint("Tipo de projeto / serviço — digite ou escolha");type.setTextColor(Color.WHITE);type.setThreshold(0);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_dropdown_item_1line,TYPES));type.setOnFocusChangeListener((v,focus)->{if(focus)type.showDropDown();});root.addView(type);watch(type);
  model=edit("Modelo / configuração, quando aplicável",false);config=edit("Detalhes do projeto e da simulação",true);
  button("TIRAR FOTO DO LOCAL",this::camera);button("IMPORTAR FOTO",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,2);});photo=image();
  label("MEDIDAS INFORMADAS PELO VIDRACEIRO",16);measureBox=new LinearLayout(this);measureBox.setOrientation(LinearLayout.VERTICAL);root.addView(measureBox);button("+ ADICIONAR MEDIDA",()->addRow("","","mm"));
  button("SALVAR PROJETO",()->{save();message("Projeto salvo neste aparelho.");});button("ABRIR PROJETO",this::open);button("NOVO PROJETO",()->new AlertDialog.Builder(this).setMessage("Salvar o atual e iniciar outro projeto?").setPositiveButton("INICIAR",(d,w)->{save();id=UUID.randomUUID().toString();setDir();load();}).setNegativeButton("VOLTAR",null).show());
  create=button("CRIAR IMAGEM COM AS MEDIDAS",this::generate);label("SIMULAÇÃO VISUAL",18);label("Apresentação ao cliente. As medidas digitadas são a referência; a imagem não define fabricação.",14);result=image();button("MOSTRAR AO CLIENTE",()->{if(!new File(dir,"simulation.png").exists()||simulation.isEmpty()){message("Crie uma simulação para os dados atuais.");return;}ImageView full=new ImageView(this);full.setImageURI(Uri.fromFile(new File(dir,"simulation.png")));full.setAdjustViewBounds(true);new AlertDialog.Builder(this).setView(full).setPositiveButton("FECHAR",null).show();});
  send=button("ENVIAR RESULTADO PARA O PDV",this::deliver);status=label("",14);load();
 }
 private void setDir(){dir=new File(getFilesDir(),"images/"+id);dir.mkdirs();getPreferences(0).edit().putString("current",id).apply();}
 private TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextColor(Color.rgb(210,235,250));v.setTextSize(size);v.setPadding(0,px(10),0,px(8));root.addView(v);return v;}
 private void style(EditText e){e.setTextColor(Color.WHITE);e.setHintTextColor(Color.LTGRAY);e.setTextSize(16);e.setPadding(px(12),px(10),px(12),px(10));GradientDrawable g=new GradientDrawable();g.setColor(Color.rgb(22,43,67));g.setCornerRadius(px(10));e.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=px(10);e.setLayoutParams(p);}
 private EditText edit(String hint,boolean multiline){EditText e=new EditText(this);style(e);e.setHint(hint);e.setSingleLine(!multiline);if(multiline)e.setMinLines(3);root.addView(e);watch(e);return e;}
 private Button button(String text,Runnable click){Button b=new Button(this);b.setText(text);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setAllCaps(false);GradientDrawable g=new GradientDrawable();g.setColor(Color.rgb(11,113,161));g.setCornerRadius(px(12));b.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,px(54));p.bottomMargin=px(10);root.addView(b,p);b.setOnClickListener(v->{try{click.run();}catch(Exception e){message(e.getMessage());}});return b;}
 private ImageView image(){ImageView v=new ImageView(this);v.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(v,new LinearLayout.LayoutParams(-1,px(240)));return v;}
 private void watch(EditText e){e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){changed();}public void afterTextChanged(Editable s){}});}
 private void changed(){if(restoring)return;revision++;simulation="";if(result!=null)result.setImageDrawable(null);if(status!=null)status.setText("Dados alterados. Crie outra simulação antes de enviar.");}
 private final class Row {EditText label,value;Spinner unit;String previous;Row(String n,String v,String u){LinearLayout line=new LinearLayout(MainActivity.this);line.setOrientation(LinearLayout.VERTICAL);label=new EditText(MainActivity.this);style(label);label.setHint("Nome da medida: largura, altura, espessura…");label.setText(n);value=new EditText(MainActivity.this);style(value);value.setHint("Valor real");value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);value.setText(v);unit=new Spinner(MainActivity.this);unit.setAdapter(new ArrayAdapter<>(MainActivity.this,android.R.layout.simple_spinner_dropdown_item,new String[]{"mm","cm","m"}));previous=u;unit.setSelection(Arrays.asList("mm","cm","m").indexOf(u));line.addView(label);line.addView(value);line.addView(unit);Button remove=new Button(MainActivity.this);remove.setText("Remover medida");line.addView(remove);remove.setOnClickListener(w->{rows.remove(this);measureBox.removeView(line);changed();});measureBox.addView(line);watch(label);watch(value);unit.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View x,int pos,long z){String next=unit.getSelectedItem().toString();if(next.equals(previous))return;try{if(!value.getText().toString().trim().isEmpty())value.setText(Measures.convert(value.getText().toString(),previous,next));previous=next;changed();}catch(Exception e){unit.setSelection(Arrays.asList("mm","cm","m").indexOf(previous));message(e.getMessage());}}});}}
 private void addRow(String n,String v,String u){if(rows.size()>=24){message("Até 24 medidas por projeto.");return;}rows.add(new Row(n,v,u));changed();}
 private JSONObject draft()throws Exception{JSONObject j=new JSONObject().put("id",id).put("title",title.getText().toString()).put("type",type.getText().toString()).put("model",model.getText().toString()).put("configuration",config.getText().toString()).put("revision",revision).put("simulationId",simulation);JSONArray a=new JSONArray();for(Row r:rows)a.put(new JSONObject().put("label",r.label.getText().toString()).put("value",r.value.getText().toString()).put("unit",r.unit.getSelectedItem()));return j.put("measures",a);}
 private JSONObject project()throws Exception{JSONObject j=draft();if(j.getString("title").trim().isEmpty()||j.getString("type").trim().isEmpty())throw new Exception("Informe nome e tipo de serviço. O tipo pode ser personalizado.");if(rows.isEmpty())throw new Exception("Informe ao menos uma medida real.");JSONArray a=new JSONArray();Set<String> names=new HashSet<>();for(Row r:rows){String name=r.label.getText().toString().trim(),u=r.unit.getSelectedItem().toString();if(name.isEmpty()||!names.add(name.toLowerCase(Locale.ROOT)))throw new Exception("Identifique cada medida sem repetir nomes.");String v=Measures.parse(r.value.getText().toString()).toPlainString();a.put(new JSONObject().put("label",name).put("value",v).put("unit",u).put("mm",Measures.mm(v,u)));}j.remove("simulationId");return j.put("schemaVersion",1).put("measures",a);}
 private void save(){try{File temp=new File(dir,"draft.tmp");Files.write(temp.toPath(),draft().toString().getBytes(StandardCharsets.UTF_8));Files.move(temp.toPath(),new File(dir,"draft.json").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}catch(Exception e){message("Não foi possível salvar o rascunho.");}}
 private void load(){restoring=true;try{JSONObject j=new File(dir,"draft.json").exists()?new JSONObject(new String(Files.readAllBytes(new File(dir,"draft.json").toPath()),StandardCharsets.UTF_8)):new JSONObject();title.setText(j.optString("title"));type.setText(j.optString("type"));model.setText(j.optString("model"));config.setText(j.optString("configuration"));rows.clear();measureBox.removeAllViews();JSONArray a=j.optJSONArray("measures");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);addRow(x.getString("label"),x.getString("value"),x.getString("unit"));}else {addRow("Largura","","mm");addRow("Altura","","mm");}revision=j.optInt("revision");simulation=j.optString("simulationId");photo.setImageURI(Uri.fromFile(new File(dir,"photo.jpg")));result.setImageDrawable(null);if(!simulation.isEmpty())result.setImageURI(Uri.fromFile(new File(dir,"simulation.png")));status.setText("Projeto local. Serviço e medidas podem ser expandidos.");}catch(Exception e){message("Não foi possível abrir o projeto salvo.");}finally{restoring=false;}}
 private void open(){save();File[] dirs=new File(getFilesDir(),"images").listFiles(File::isDirectory);if(dirs==null)return;ArrayList<File> list=new ArrayList<>();ArrayList<String> names=new ArrayList<>();for(File d:dirs)try{JSONObject j=new JSONObject(new String(Files.readAllBytes(new File(d,"draft.json").toPath()),StandardCharsets.UTF_8));list.add(d);names.add(j.optString("title","Sem título")+" • "+j.optString("type"));}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("Projetos deste aparelho").setItems(names.toArray(new String[0]),(x,n)->{id=list.get(n).getName();setDir();load();}).show();}
 private void camera(){File f=new File(dir,"capture.jpg");Uri u=FileProvider.getUriForFile(this,getPackageName()+".files",f);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE).putExtra(MediaStore.EXTRA_OUTPUT,u).addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("foto",u));if(i.resolveActivity(getPackageManager())==null){message("Câmera indisponível. Use importar foto.");return;}startActivityForResult(i,1);}
 @Override protected void onActivityResult(int req,int code,Intent data){super.onActivityResult(req,code,data);if(code!=RESULT_OK)return;try{Uri u=req==1?Uri.fromFile(new File(dir,"capture.jpg")):data.getData();BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(u)){BitmapFactory.decodeStream(in,null,opts);}opts.inSampleSize=Math.max(1,Math.max(opts.outWidth,opts.outHeight)/1600);opts.inJustDecodeBounds=false;Bitmap b;try(InputStream in=getContentResolver().openInputStream(u)){b=BitmapFactory.decodeStream(in,null,opts);}if(b==null)throw new IOException();int orient;try(InputStream in=getContentResolver().openInputStream(u)){orient=new ExifInterface(in).getAttributeInt(ExifInterface.TAG_ORIENTATION,1);}Matrix m=new Matrix();if(orient==6)m.postRotate(90);if(orient==3)m.postRotate(180);if(orient==8)m.postRotate(270);Bitmap normalized=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),m,true);try(FileOutputStream out=new FileOutputStream(new File(dir,"photo.jpg"))){normalized.compress(Bitmap.CompressFormat.JPEG,90,out);}photo.setImageURI(null);photo.setImageURI(Uri.fromFile(new File(dir,"photo.jpg")));changed();save();}catch(Exception e){message("Não foi possível importar a foto.");}}
 private void connection(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(px(18),px(12),px(18),0);EditText url=new EditText(this),token=new EditText(this);url.setHint("URL HTTPS do serviço");url.setText(getSharedPreferences("connection",0).getString("url",""));token.setHint("Código de conexão fornecido pelo serviço");token.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(url);box.addView(token);new AlertDialog.Builder(this).setTitle("Conectar ao serviço").setView(box).setPositiveButton("SALVAR",(d,w)->{try{URI u=new URI(url.getText().toString().trim());if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new Exception("Use uma URL HTTPS válida.");if(token.getText().length()>0)Vault.save(this,token.getText().toString());getSharedPreferences("connection",0).edit().putString("url",u.toString().replaceAll("/+$","")).apply();message("Conexão salva. Será validada no próximo pedido.");}catch(Exception e){message(e.getMessage());}}).setNegativeButton("VOLTAR",null).show();}
 private JSONObject request(String path,JSONObject body)throws Exception{String endpoint=getSharedPreferences("connection",0).getString("url","");String token=Vault.read(this);if(endpoint.isEmpty()||token.isEmpty())throw new Exception("Configure o serviço HTTPS e o código de conexão. Nenhuma imagem foi enviada.");HttpURLConnection c=(HttpURLConnection)new URL(endpoint+path).openConnection();c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(180000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+token);try{try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()!=200)throw new Exception("Serviço não concluiu a operação ("+c.getResponseCode()+"). Tente novamente após conferir a conexão.");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>20000000)throw new IOException("Resposta muito grande.");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 private void busy(boolean value){busy=value;create.setEnabled(!value);send.setEnabled(!value);}
 private void generate(){if(busy)return;try{JSONObject spec=project();File p=new File(dir,"photo.jpg");if(!p.exists())throw new Exception("Tire ou importe a foto do local.");String encoded=android.util.Base64.encodeToString(Files.readAllBytes(p.toPath()),2);int expected=revision;String projectId=id;File target=dir;save();busy(true);status.setText("Criando simulação… mantenha o projeto sem alterações.");worker.execute(()->{try{JSONObject response=request("/v1/simulations",new JSONObject().put("project",spec).put("photoBase64",encoded));byte[] image=android.util.Base64.decode(response.getString("imageBase64"),0);runOnUiThread(()->{if(isDestroyed())return;busy(false);if(!id.equals(projectId)||revision!=expected){status.setText("Projeto alterado. A imagem antiga não foi aplicada.");return;}try{Files.write(new File(target,"simulation.png").toPath(),image);simulation=response.getString("simulationId");result.setImageURI(null);result.setImageURI(Uri.fromFile(new File(target,"simulation.png")));save();status.setText("Simulação criada para os dados atuais. Revise antes de apresentar.");}catch(Exception e){message("Não foi possível salvar a imagem.");}});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;busy(false);message(e.getMessage());});}});}catch(Exception e){message(e.getMessage());}}
 private void deliver(){if(busy)return;if(simulation.isEmpty()){message("Crie uma imagem para os dados atuais antes de enviar.");return;}String job=simulation;busy(true);worker.execute(()->{try{JSONObject response=request("/v1/projects",new JSONObject().put("simulationId",job));runOnUiThread(()->{if(isDestroyed())return;busy(false);status.setText("Pacote recebido na caixa de entrada: "+response.optString("receiptId")+". Aguarda importação no PDV.");});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;busy(false);message(e.getMessage());});}});}
 private void message(String s){if(!isFinishing())new AlertDialog.Builder(this).setMessage(s==null?"Operação não concluída.":s).setPositiveButton("OK",null).show();}
 @Override protected void onPause(){save();super.onPause();}
 @Override protected void onDestroy(){worker.shutdown();super.onDestroy();}
}
